{
  "sop_id": "SOP-020",
  "title": "Leave Applications (HR)",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create leave ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Assign ticket to self",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Check leave balance",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Verify employee eligibility for leave type",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Record leave dates (excluding holidays and weekly offs)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Submit leave application",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "D1",
      "name": "Lead approval (if leave duration > 10 days)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit (if rejected by Incharge)",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "leave duration > 10 days"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
